menuitem.script:
 
				
					
					var comHelperMethods = function(){
						var isBadHresult = function( prop ){
							if (typeof(window.external.application[prop]) === "unknown") return true;		
							return false;
						};				
						
						var isNullUndefinedBlankOrEmptyString = function( prop ){
							if (!window.external.application[prop]) return true;
							if (window.external.application[prop].replace(/ /g,'') === "") return true;
							return false;
						};				
						
						var isPropertyValid = function( prop ){
							if (isBadHresult( prop )) return false;						
							if (isNullUndefinedBlankOrEmptyString( prop )) return false;
							return true;				
						};	
					
						return{
							isPropertyValid: isPropertyValid
						};
					};	
					
					
					// expose helperMethods through the window object
					// to be used by the other jsHandlers (e.g. onclick):
					window.comHelperMethods = new comHelperMethods();
					
					
					
					var shouldMenuItemBeHidden = function(){
						return ((!window.comHelperMethods.isPropertyValid("CurrentPointID")) && (!window.comHelperMethods.isPropertyValid("DetailPointID")))
					};
				
				
					// The actual check:
					if (shouldMenuItemBeHidden()){
						this.style.display ="none";
					}			
					
					return true;

 
				 
				 	
					var CopiedTxt;
				  
					if (window.comHelperMethods.isPropertyValid("CurrentPointID"))
					{
						CopiedTxt = window.external.application.CurrentPointID;
					}
					  
					else if (window.comHelperMethods.isPropertyValid("DetailPointID"))
					{
						CopiedTxt= window.external.application.DetailPointID;
					}
					  
					else CopiedTxt=" "; 
							   
					clipboardData.setData("Text",CopiedTxt); 
					window.external.CloseShortcutMenu();
